export function getVehicleImageFileName(nameOrId: string | undefined): string | null {
  if (!nameOrId) return null;
  const direct = VEHICLE_IMAGE_MAP[nameOrId];
  if (direct) return direct;
  
  const norm = nameOrId.toLowerCase().trim().replace(/[^a-z0-9]/g, "");
  for (const key of Object.keys(VEHICLE_IMAGE_MAP)) {
    if (key.toLowerCase().trim().replace(/[^a-z0-9]/g, "") === norm) {
      return VEHICLE_IMAGE_MAP[key];
    }
  }
  return null;
}

export function getVehicleImageUrl(nameOrId: string | undefined, hostUrl?: string): string | null {
  const fileName = getVehicleImageFileName(nameOrId);
  if (!fileName) return null;
  const path = `/images/vehicles/${encodeURIComponent(fileName)}`;
  if (hostUrl) {
    return `${hostUrl.replace(/\/+$/, "")}${path}`;
  }
  return path;
}
